import{_ as p,l as n,o as e,c as i,v as r,p as l,x as o,d as s,i as c,S as u}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"Parquet / ORC","description":"","frontmatter":{"title":"Parquet / ORC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/parquet-orc.md","filePath":"cs/parquet-orc.md","lastUpdated":1789023840000}'),d={name:"cs/parquet-orc.md"};function h(m,a,_,q,P,f){const t=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="parquet-orc" tabindex="-1">Parquet / ORC <a class="header-anchor" href="#parquet-orc" aria-label="Permalink to &quot;Parquet / ORC&quot;">​</a></h1><div class="epigraph"><p>开放列存文件把 row group、列块、编码与页统计写成可交换合同，让引擎不必共享缓冲池也能共享数据。</p><footer>—— 据 Apache Parquet 格式；Apache ORC；Dremel / C-Store 谱系</footer></div><p><a href="/cs/column-compression">上一课</a>给出块内编码。本课不选 RLE 阈值。缺口是<strong>文件级标准</strong>：数据湖与多引擎（Spark、专用 OLAP、入库工具）要读同一份字节。Parquet 与 ORC 把 PAX 思想放到文件：footer、row group、column chunk、page、min/max 与字典。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>专有表空间把数据锁在一种引擎。分析把表卸成文件后，格式必须自描述：哪些列、编码、压缩、统计、嵌套（Parquet 的 repetition/definition 来自 Dremel）。缺口不是「大数据产品课」，而是存储进阶里的开放页格式，相对 InnoDB 页只在一个缓冲池里。</p><p>谓词下推进文件：读 footer 的 zone 统计，跳过 row group；再读列块统计，跳过 page。这是后课 zone map 的文件实例。嵌套结构不是文档库：仍是列存的嵌套编码。</p><p><span class="marginnote">Parquet 源自 Google Dremel 的列式嵌套；ORC 来自 Hive。本课对照合同，不背所有 version 字段。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写：按 row group 切（行数或字节阈值），每列一块，选编码与可选压缩器（与编码叠）。读：投影列集合 → 只打开那些 chunk；谓词 → 用统计裁剪。schema 演化：加列、可选字段，与模式迁移课的文件版。</p><p>与事务：文件通常不可变，更新靠写新文件+元数据提交（湖仓表格式后课）。本课单个文件内部。</p>',10)),(e(),l(u,null,{default:o(()=>[c(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%96%87%E4%BB%B6%20footer%22%5D%20--%3E%20RG%5B%22row%20group%22%5D%0A%20%20RG%20--%3E%20CC%5B%22column%20chunk%22%5D%0A%20%20CC%20--%3E%20PG%5B%22page%20%2B%20%E7%BB%9F%E8%AE%A1%22%5D%0A%20%20PRED%5B%22%E8%B0%93%E8%AF%8D%22%5D%20--%3E%20SKIP%5B%22%E8%B7%B3%E8%BF%87%20group%20%2F%20page%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>向量化扫描直接吃 page 解成列向量。并行：按 row group 切给工人，exchange 前已是列批次。小文件问题：每个文件一个 footer，调度税高——后课表格式用 compaction 合文件，与 LSM 同构。</p><p>类型系统：十进制、时间戳精度不一致会在引擎间产生静默错，合同要钉。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Iceberg/Delta 的快照日志写完。也不讲位图索引在库内的实现——后课。ORC 的索引流、Parquet 的 bloom 模块点名存在。</p><p>后课默认：分析交换用 Parquet/ORC 一类列文件。zone map 与跳过索引：min/max 与更一般的跳过结构，库内表也用。</p><p>开放格式把「页」从一种引擎的缓冲池里解放出来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Parquet/ORC 标准化 row group、列块、编码与统计。</li><li>谓词用统计跳过；文件不可变，事务在元数据层。</li><li>zone map 下一课：把跳过从文件合同收回库内表。</li><li>出处：Apache Parquet；Apache ORC；Dremel。</li></ul>',9))])}const A=p(d,[["render",h]]);export{C as __pageData,A as default};
